    "enunciado": "... Leia o texto a seguir: Iate de luxo de R$ 5 milhões afunda segundos após lançamento na Turquia Dolce Vento virou durante sua viagem inaugural em Zonguldak; ninguém se feriu Um iate de luxo virou e afundou poucos minutos após ser lançado ao mar durante sua viagem inaugural na costa de Zonguldak, no norte da Turquia, nesta terça-feira. O incidente, que deixou passageiros em pânico, foi registrado em vídeo e rapidamente se espalhou pelas redes sociais. O barco, chamado Dolce Vento, avaliado em £ 700 mil (cerca de R$ 5,1 milhões), começou a inclinar-se segundos após o lançamento. O navio, com comprimento entre 24 e 30 metros, foi construído no estaleiro Med Yilmaz e entregue ao proprietário em Istambul, de acordo com o jornal inglês The Sun. Apesar da gravidade da situação, todos a bordo — o proprietário, o capitão e dois tripulantes — conseguiram nadar até a costa sem ferimentos. Imagens captadas por celular mostram um dos ocupantes subindo nos destroços parcialmente submersos e pulando na água. Equipes da guarda costeira e do porto foram enviadas para controlar a área e iniciar os trabalhos de resgate e recuperação. Autoridades do estaleiro afirmaram que uma investigação será conduzida para determinar a causa do naufrágio. Fonte: r-5-milhoes-afunda-segundos-aposlancamento-na-turquia-veja-video.ghtml?li_ source=LI&li_medium=news-page-widget. Texto adaptado. Acesso em 03/09/2025 No título do texto, “Iate de luxo de R$ 5 milhões afunda segundos após lançamento na Turquia”, se o verbo em destaque estivesse conjugado no pretérito imperfeito do indicativo, teríamos:",
