    "enunciado": "Leia o texto a seguir: Uso de dispositivos eletrônicos por crianças de 2 a 6 anos deve ocorrer apenas com a mediação ativa de adultos, diz projeto de lei aprovado na Câmara A Câmara dos Deputados aprovou projeto de lei que prevê medidas de proteção para a primeira infância (até 6 anos) no ambiente digital. A proposta será enviada ao Senado. De autoria do deputado Marcos Tavares (PDT-RJ), o Projeto de Lei 1971/25 foi aprovado nesta quarta-feira (15) na forma de um substitutivo da relatora em Plenário, deputada Flávia Morais (PDT-GO). O texto aprovado modifica a lei sobre políticas para a primeira infância (Lei 13.257/16) para considerar área prioritária, no âmbito das políticas públicas destinadas a esse público, a proteção no ambiente digital. O objetivo é garantir que o uso das tecnologias digitais seja realizado de forma segura, saudável, consciente e apenas quando estritamente necessário para resguardar o melhor interesse da criança. Segundo a relatora, o texto resgata propostas do grupo de trabalho criado pela Câmara para debater a proteção de crianças e adolescentes no ambiente digital. \"Entre as principais recomendações destacam-se o fortalecimento do sistema de garantias de direitos, a criação de políticas de prevenção baseadas em evidências científicas, a estruturação de redes de A deputada destacou que o projeto também valoriza \"as experiências presenciais, as interações humanas, as atividades lúdicas e as brincadeiras reais como eixos centrais do desenvolvimento físico, emocional, cognitivo e social\". Fonte: “A Câmara dos Deputados aprovou projeto de lei que prevê medidas de proteção para a primeira infância (até 6 anos) no ambiente digital” (1º parágrafo). Nesse trecho, a forma verbal em destaque está flexionada no:",
