    "enunciado": "Professor de Educação Infantil ... Leia o texto a seguir: Amazônia e Cerrado registram queda de 11% no desmatamento O desmatamento na Amazônia e no Cerrado diminuiu no período de agosto de 2024 a julho de 2025, segundo dados do Projeto de Monitoramento do Desmatamento na Amazônia Legal por Satélite (Prodes), do Instituto Nacional de Pesquisas Espaciais (Inpe). Na Amazônia, a queda foi de 11,08% em relação ao período anterior, de agosto de 2023 a julho de 2024. Já no Cerrado, a queda foi de 11,49%. Os dados foram divulgados nesta quinta-feira (30), pelo Ministério do Meio Ambiente e Mudança Climática (MMA). Na Amazônia, os dados mostram que foram queimados 5.796 km². Esta é a terceira menor taxa da série histórica, que começou a ser medida em 1988, e o terceiro ano consecutivo de redução. Os estados que mais contribuíram com o desmatamento foram o Pará, Mato Grosso e Amazonas, que responderam, juntos, por 80% de todo o desmatamento na Amazônia Legal. O Tocantins registrou a maior queda proporcional, com 62%. A queda pode ser explicada porque o estado possui uma área de f l oresta menor que os outros integrantes da Amazônia Legal. O Amapá teve uma queda de 42%; Roraima apresentou queda de 37%. Em Rondônia, a redução foi de 33%. O Acre registrou queda de 27%, consolidando uma tendência na região desde 2021. Já no Maranhão, a queda foi de 26%; e no Amazonas o percentual foi de 16,93%. Ainda que exista uma queda do desmatamento, uma coisa que chama atenção é o incremento da área desmatada por degradação progressiva, com grandes incêndios florestais que chegam a levar a floresta ao colapso, afirmou o coordenador do Programa BiomasBR do Inpe, Cláudio Almeida. Ele destaca o aumento de 25,05% no desmatamento em Mato Grosso, estado bastante afetado por incêndios. Fonte: No título do texto (“Amazônia e Cerrado registram queda de 11% no desmatamento”), a forma verbal em destaque está flexionada no:",
