    "assunto": "Morfologia - Tempos e Modos Verbais",
    "enunciado": "Chuvas no Rio Grande do Sul devastam o Estado, provocando mortes e o deslocamento de populações Pedro Luiz Côrtes, da USP, aponta três motivos para a tragédia: frentes frias, umidade oceânica e uma barreira de alta pressão. Governo federal suspende restrições legais para a reconstrução Jornal da USP no Ar Texto: Redação “É um desastre que se colocaria, sem exagero, no rol de um grande terremoto”, disse ao Jornal da USP o professor Pedro Luiz Côrtes, do Instituto de Energia e Ambiente da Universidade de São Paulo. “As enchentes afetam o Estado de formas tão abrangentes e intensas que é possível fazer essa comparação”, acrescenta. “A necessidade de reconstrução é praticamente total, porque todos os principais recursos de que o Estado e a população podem dispor foram comprometidos no seu todo ou em grande parte”, aponta Côrtes. Acomeçar pela infraestrutura do transporte. Na sua visão, além da dificuldade de locomoção, evacuação dos locais e resgate de vítimas, a segurança alimentar e energética são dificuldades consequentes. Sem meios de levar comida e energia, a fome, a distribuição de combustível e a impossibilidade de recuperar a rede elétrica se tornam problemas também. Para Côrtes, a saúde é mais um ponto preocupante de atenção. “Mesmo as cidades que não tiveram o fornecimento de água comprometido, mas que sofreram com alagamentos, podem ter contaminação das redes de distribuição de água. Infelizmente, isso pode ampliar as doenças de veiculação hídrica, como é o caso da hepatite e da leptospirose, por exemplo”. Não havia enchentes da grandeza da ocorrida na semana passada no Rio Grande do Sul desde 1941, que na época registrou picos de 4,76 metros. A da semana passada atingiu 5,31 metros. A locução verbal na frase “Não havia enchentes da grandeza da ocorrida na semana passada no Rio Grande do Sul desde algo no passado. De acordo com o texto 1, marque a opção abaixo que NÃO substitui o contexto da situação apresentada:",
