    "assunto": "Morfologia - Tempos e Modos Verbais",
    "enunciado": "Provas: SELECON - 2024 - Prefeitura de São Gonçalo - RJ - Professor Docente II ... Leia o texto a seguir: Vítima de pólio vive dentro de pulmão de aço há 70 anos e viraliza no TikTok Pessoa que está há mais tempo dentro do aparelho no mundo, Paul Alexander se formou em advocacia e escreveu um livro sobre sua história Com 77 anos, Paul Alexander é o paciente que vive há mais tempo dentro de um pulmão de aço, também chamado de pulmão de ferro, segundo o Guinness World Records. Vítima de uma paralisia dos músculos do peito decorrente da poliomielite, Paul precisou ser colocado no aparelho ainda em 1952, quando tinha apenas 6 anos de idade. Agora, com o perfil “ironlungman” (“homem pulmão de aço”), o morador de Dallas, nos Estados Unidos, viraliza no TikTok com vídeos sobre como foi crescer dentro da máquina e a sua rotina hoje em dia. Na primeira postagem, que conta com mais de tem sonhos como qualquer outra pessoa. — Em 1952, durante uma epidemia de poliomielite, contraí a doença e estou paralisado desde então. E vivo num pulmão de aço porque não consigo respirar sozinho. Fui para a escola com o meu pulmão de aço, agora sou advogado, exerci a advocacia durante 30 anos, escrevi um livro e o divulguei ao mundo sobre mim e a minha poliomielite, e milhões de pessoas sabem o meu nome hoje. Tenho objetivos e sonhos de fazer mais algumas coisas (...) — disse. Na publicação, ele passa uma mensagem ainda para todas as crianças que não se vacinaram contra a doença: — Quero falar ao mundo sobre a poliomielite e sobre as milhões de crianças que não estão protegidas contra a poliomielite, que precisam ser protegidas antes que haja outra epidemia. Fonte: A partir do verbo PUBLICAR, obtém-se PUBLICAÇÃO, que é uma palavra derivada. O elemento destacado é classificado como:",
