    "assunto": "Morfologia - Tempos e Modos Verbais",
    "enunciado": "Merendeira Texto I AS ENCHENTES Lima Barreto As chuvaradas de verão, quase todos os anos, causam no nosso Rio de Janeiro inundações desastrosas. Além da suspensão total do tráfego, com uma prejudicial interrupção das comunicações entre os vários pontos da cidade, essas inundações causam desastres pessoais lamentáveis, muitas perdas de haveres e destruição de imóveis. De há muito que a nossa engenharia municipal se devia ter compenetrado do dever de evitar tais acidentes urbanos. Uma arte tão ousada e quase tão perfeita, como é a engenharia, não deve julgar irresolvível tão simples problema. Não sei nada de engenharia, mas, pelo que me dizem os entendidos, o problema não é tão difícil de resolver como parece fazerem constar os engenheiros municipais. O prefeito Passos, que tanto se interessou pelo embelezamento da cidade, descurou completamente de solucionar esse defeito do nosso Rio. Cidade cercada de montanhas e entre montanhas, que recebe violentamente grandes precipitações atmosféricas, o seu principal defeito a vencer era esse acidente das inundações. Infelizmente, porém, nos preocupamos muito com os aspectos externos, com as fachadas, e não com o que há de essencial nos problemas da nossa vida urbana, econômica, financeira e social. Fonte: Texto adaptado de Na frase “O prefeito Passos, que tanto se interessou pelo embelezamento da cidade, descurou completamente de solucionar esse defeito do nosso Rio” (3º parágrafo), o verbo destacado apresenta sentido de:",
