    "assunto": "Morfologia - Tempos e Modos Verbais",
    "enunciado": "Judiciária A longa caminhada do nosso cérebro Ao longo de milhões de anos de caminhada aleatória, a evolução natural no planeta Terra costurou uma rede tridimensional, composta de feixes, folhas e bobinas de substância branca neural. Conduzindo e acelerando cargas eletrobiológicas diminutas, geradas por dezenas de bilhões de neurônios, esse arcabouço orgânico pariu um tipo de interação eletromagnética única, a qual dotou o cérebro de primatas de um precioso presente: o seu próprio ponto de vista. De dentro da sinfonia recursiva e imprevisível produzida por esse computador orgânico analógico-digital, o cérebro nosso emergiu e dominou com requintes de virtuosidade o mecanismo biológico essencial da vida, que consiste em dissipar energias inúteis para embutir informações ricas em significado na própria carne. A partir dessa receita de sobrevivência, nosso cérebro fez muito mais que simplesmente viver: ele construiu O universo humano usando a sopa de informação potencial generosamente oferecida pelo cosmos. Esse trabalho hercúleo só foi possível devido ao acúmulo cada vez maior de informação útil, de modo a que nosso cérebro desse acesso a formas de conhecimento, tecnologias, linguagens, interações sociais e construção da nossa realidade. O que o futuro reserva para tanto trabalho cerebral? Autoaniquilação, uma nova espécie humana feita de zumbis biológicos digitais, ou o ansiado triunfo perene da condição humana? Seja qual for o destino reservado para essa trabalhosa jornada, certamente não haverá máquina capaz de superar as mais íntimas e doidivanas alegorias criadas por nosso cérebro. Muito menos de substituir o espantoso universo que ele criou. (Adaptado de: NICOLELIS, Miguel, O Verdadeiro Criador de Tudo. São Paulo: Planeta, 2020, p. 373-374) Chegará o dia em que haveremos de compor uma horda de zumbis a que venha a faltar uma real criatividade? Uma adequada articulação entre os tempos e os modos verbais da frase acima persistirá caso se substituam os elementos sublinhados, na ordem dada, por:",
