    "materia": "Língua Portuguesa",
    "assunto": "Morfologia - Tempos e Modos Verbais",
    "enunciado": "Flexão verbal de modo (indicativo, subjuntivo, imperativo) Administrativa [Vida a compartilhar] Um jovem amigo meu é uma pessoa exasperada e deprimida. Na semana passada, ele foi atraído por uma história edificante. Uma escola americana dedicara um anfiteatro a uma professora de escola fundamenta! que, depois de uma longa carreira de ensino, foi paralisada por uma distrofia muscular, e seguiu ensinando. Quando perdeu a voz, passou a ensinar surdos-mudos. Na reportagem, ela estranhava a atenção e os elogios: era uma mulher em paz consigo mesma e com o mundo, sem furores caritativos ou vocações martirológicas. Sua vida parecia simplesmente normal. Meu jovem amigo comentou que, se estivesse no lugar dela, já teria acabado com sua própria vida. Essa ideia, concordei, passaria por qualquer cabeça. Mas por que a professora não foi por esse caminho? O insuportável numa doença como essa, afirmou então meu interlocutor, são os limites, as impotências. Observei-lhe então que há uma infinidade de coisas que não conseguimos fazer. Afinal, não sei voar, nem ficar por respirar mais que dois minutos. Com paciência condescendente, meu amigo explicou que essas são coisas que ninguém, ou quase ninguém, consegue fazer O que dói, acrescentou, é não conseguir fazer as coisas que os outros conseguem. E declarou que, se tivesse uma invalidez grave, talvez pudesse seguir vivendo, mas só entre pessoas tão inválidas quanto ele. Conclusão da conversa: o problema não é a invalidez, o problema são os outros. Melhor dizendo, a necessidade de se comparar aos outros. De todo modo, ficamos sem apurar que tipo de energia animava aquela prejudicada professora, excepcionalmente apta e disposta a só compartilhar o que tinha de positivo. (Adaptado de: CALLIGARIS, Contardo. Terra de ninguém. São Paulo: Publifolha, 2004, p. 70-71) É adequada a articulação entre os tempos e modos verbais na seguinte frase:",
    "alternativas": [
      {
        "id": "A",
        "texto": "Ficamos sem saber por que vem ela se dedicado a atos virtuosos que sua doença lhe impedisse de haver praticado."
      },
      {
        "id": "B",
        "texto": "Quando perdesse a voz, em função da distrofia que lhe acometeria, ela passará a ensinar surdos e mudos."
      },
      {
        "id": "C",
        "texto": "Fora uma mulher em paz consigo mesma, apesar dos sofrimentos que a vida lhe reserve, ao desafiar seus limites."
      },
      {
        "id": "D",
        "texto": "Quando me confessou que se mataria, não me surpreendi e disse que muita gente poderia vir a tomar igual decisão."
      },
      {
        "id": "E",
        "texto": "Segundo meu amigo, a dor maior comparece quando nos convencêssemos de que não sejamos os únicos a sofrer."
      }
    ],
